import logging
from collections import namedtuple
from datetime import timedelta

from taf.transport.ssh.connection import SSHConnection

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class SshOutput(namedtuple('SshOutput', ['stdout', 'stderr', 'rc'])):
    __slots__ = ()

    def __new__(cls, stdout, stderr='', rc=-1):
        return super().__new__(cls, stdout, stderr, rc)


class SshNode:
    def __init__(self, hostname, username, password):
        self.hostname = hostname
        self.username = username
        self.password = password
        self.ssh_connection = SSHConnection()
        self.ssh_connection.configure(hostname=hostname, username=username, password=password)
        self.nested_connections = 0
        self._fqdn = None

    def connect(self):
        self.ssh_connection.connect()

    def execute_command(self, command, ignore_stderr=False, ignore_rc=False, timeout=None):
        process = self.ssh_connection.send_command(command, timeout=timeout)
        process.join(timeout=timeout)
        stderr = process.read_error().strip()
        stdout = process.read_output().strip()
        rc = process.get_exit_code()
        if stderr or rc > 0:
            exc_msg = (f'\ncommand: {command}\n'
                       f'exit code: {rc}\n'
                       f'stderr:\n{stderr}\n'
                       f'stdout:\n{stdout}')
            if (stderr and not ignore_stderr) or (rc > 0 and not ignore_rc):
                raise IOError(exc_msg)
            else:
                logger.warning(exc_msg)
        return SshOutput(stdout=stdout, stderr=stderr, rc=rc)

    @property
    def files(self):
        return self.ssh_connection.files

    def file_exists(self, remote_path, timeout=None):
        """Return True if file exists on the remote, False otherwise."""
        return self.files.exists(remote_path, timeout)

    def get_file(self, remote_file, local_file, timeout=None):
        """Copy a remote file (remote_path) to the local host (local_path)."""
        return self.files.get(remote_file, local_file, timeout)

    def put_file(self, local_file, remote_file, timeout=None):
        """Copy a local file (local_file) to the remote host (remote_file)."""
        return self.files.put(local_file, remote_file, timeout)

    def put_file_content(self, file_content, remote_file):
        """Put content to a remote file."""
        with self.files.open(remote_file, 'w') as fh:
            fh.write(file_content)

    def get_file_size(self, remote_file):
        """
        :param remote_file: path to remote file
        :rtype: int
        """
        return self.files.stat(remote_file).st_size

    def get_file_content(self, remote_file):
        with self.files.open(remote_file, 'r') as fh:
            return fh.read()

    def get_time_zone(self):
        """
        :return: Time zone in string format +/-HHMM e.g. +0300) and datetime.timedelta.
        :rtype: (string, datetime.timedelta)
        """
        time_zone = self.execute_command('date +%z').stdout
        return time_zone, timedelta(hours=int(time_zone[:3]), minutes=int(time_zone[0] + time_zone[3:]))

    @property
    def fqdn(self):
        """
        :return: Fully Qualified Domain Name of the node.
        :rtype: str
        """
        if self._fqdn is None:
            self._fqdn = self.execute_command('hostname -f').stdout
        return self._fqdn

    def disconnect(self):
        if self.ssh_connection.is_connected:
            self.ssh_connection.disconnect()

    def __enter__(self):
        if self.ssh_connection.is_connected:
            self.nested_connections += 1
        elif not self.nested_connections:
            self.connect()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        if not self.nested_connections:
            self.disconnect()
        else:
            self.nested_connections -= 1
